const REPO_ROOT = join(dirname(fileURLToPath(import.meta.url)), '..', '..');

export function parseArgs(argv) {
  const options = { fresh: false, detach: false, apps: null, seed: true, limesurvey: false };
  for (const arg of argv) {
    if (arg === '--fresh') {
      options.fresh = true;
    } else if (arg === '--detach') {
      options.detach = true;
    } else if (arg === '--no-seed') {
      options.seed = false;
    } else if (arg === '--with-limesurvey') {
      options.limesurvey = true;
    } else if (arg.startsWith('--apps=')) {
      options.apps = arg.slice('--apps='.length);
    } else {
      throw new Error(
        `Unknown option "${arg}". Valid: --fresh, --detach, --no-seed, --apps=<names>, --with-limesurvey.`,
      );
    }
  }
  return options;
}

// `--profile limesurvey` has to sit before the subcommand, exactly like the `--profile seed` call
// below it already does — both are `docker compose` global flags, not arguments to `up` itself.
export function seedArgs() {
  return [
    '--profile',
    'seed',
    'up',
    '--force-recreate',
    '--exit-code-from',
    'sample-data-loader',
    'sample-data-loader',
  ];
}

